&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;Mort-vivant&lt;/a&gt; de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +5 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +14
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 20, contact 15, pris au d&#233;pourvu 15 (armure +3, Dex +5, naturelle +2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 80 (8 DV ; 2d8+6d10+38)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +10, &lt;b&gt;Vig&lt;/b&gt; +9, &lt;b&gt;Vol&lt;/b&gt; +8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Canalisation-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la canalisation (Ext)&quot;&gt;r&#233;sistance &#224; la canalisation&lt;/a&gt; +2 ; &lt;b&gt;Immunit&#233;&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Des-Morts-Vivants-(Capacit&#233;).html&quot; title=&quot;Traits des morts-vivants (Ext)&quot;&gt;traits des morts-vivants&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 12 m (8 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;morsure +1&lt;/i&gt;, +13 (1d6+3 plus &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html#FIEVREDESGOULES&quot; title=&quot;Goule&quot;&gt;maladie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt;) et 2 &lt;i&gt;griffes +1&lt;/i&gt;, +14 (1d8+3 plus &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; arc long composite de ma&#238;tre, +13/+8 (1d8+2/&#215;3)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemi jur&#233;&lt;/a&gt; (elfes +2, humains +4), &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html#FIEVREDESGOULES&quot; title=&quot;Goule&quot;&gt;maladie&lt;/a&gt; (DD 15), &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt; (1d4+1 rounds, DD 15, elfes immunis&#233;s contre cet effet), &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#DONDESTYLEDECOMBAT&quot; title=&quot;Le r&#244;deur&quot;&gt;style de combat&lt;/a&gt; (combat &#224; distance)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Sorts de r&#244;deur pr&#233;par&#233;s&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 3 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +6)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Pas.html&quot; title=&quot;Grand pas&quot;&gt;grand pas&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique.html&quot; title=&quot;Morsure magique&quot;&gt;morsure magique&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; Le grand veneur lance &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Pas.html&quot; title=&quot;Grand pas&quot;&gt;grand pas&lt;/a&gt;&lt;/i&gt; et utilise sa &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baguettes-Magiques.html&quot; title=&quot;Les baguettes magiques&quot;&gt;baguette&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; sur lui et son compagnon animal.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Voici les statistiques du grand veneur sans &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Pas.html&quot; title=&quot;Grand pas&quot;&gt;grand pas&lt;/a&gt;&lt;/i&gt; ni &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; : &lt;b&gt;VD&lt;/b&gt; 9m ; &lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +12 (1d6+2 plus &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html#FIEVREDESGOULES&quot; title=&quot;Goule&quot;&gt;maladie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt;) et 2 griffes, +13 (1d8+2 plus &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 15, &lt;b&gt;Dex&lt;/b&gt; 20, &lt;b&gt;Con&lt;/b&gt; -, &lt;b&gt;Int&lt;/b&gt; 13, &lt;b&gt;Sag&lt;/b&gt; 16, &lt;b&gt;Cha&lt;/b&gt; 18
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +7, &lt;b&gt;BMO&lt;/b&gt; +9, &lt;b&gt;DMD&lt;/b&gt; 24
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Arme-Naturelle-Sup&#233;rieure.html&quot; title=&quot;Arme naturelle sup&#233;rieure&quot;&gt;Arme naturelle sup&#233;rieure&lt;/a&gt; (griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cadavre-De-Compagnie.html&quot; title=&quot;Cadavre de compagnie&quot;&gt;Cadavre de compagnie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Endurance.html&quot; title=&quot;Endurance&quot;&gt;Endurance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-&#192;-Bout-Portant.html&quot; title=&quot;Tir &#224; bout portant&quot;&gt;Tir &#224; bout portant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-Rapide.html&quot; title=&quot;Tir rapide&quot;&gt;Tir rapide&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +13 (+17 pour sauter), &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +13, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; +13, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +14
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun, commun des profondeurs
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#EMPATHIESAUVAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;empathie sauvage&lt;/a&gt; +10, &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt; (sous terre +2), &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PACTEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;pacte du chasseur&lt;/a&gt; (compagnon animal), &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PISTAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;pistage&lt;/a&gt; +3
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Tueuse.html&quot; title=&quot;tueuse (propri&#233;t&#233;)&quot;&gt;tueuses d’humains +1&lt;/a&gt;&lt;/i&gt; (3), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Traqueuse.html&quot; title=&quot;traqueuse (propri&#233;t&#233;)&quot;&gt;traqueuses +1&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potion&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Blessure-Mod&#233;r&#233;e.html&quot; title=&quot;Blessure mod&#233;r&#233;e&quot;&gt;blessure mod&#233;r&#233;e&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baguettes-Magiques.html&quot; title=&quot;Les baguettes magiques&quot;&gt;baguette&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; (12 charges)
; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir clout&#233;e de ma&#238;tre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arc-Long-Composite-(Arme).html&quot; title=&quot;Arc long composite&quot;&gt;arc long composite de ma&#238;tre&lt;/a&gt; avec &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;50 fl&#232;ches&lt;/a&gt;, 42 po
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BDtitre&quot;&gt;Cadavre f&#233;lin&lt;div style=&quot;float:right;&quot;&gt;FP -&lt;/div&gt;&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; -
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;Mort-vivant&lt;/a&gt; de taille P, N
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +6 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +5
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 20, contact 17, pris au d&#233;pourvu 14 (Dex +6, naturelle +3, taille +1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 16 (3d8+3)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +9, &lt;b&gt;Vig&lt;/b&gt; +4, &lt;b&gt;Vol&lt;/b&gt; +2
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Immunit&#233;&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Des-Morts-Vivants-(Capacit&#233;).html&quot; title=&quot;Traits des morts-vivants (Ext)&quot;&gt;traits des morts-vivants&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 15 m (10 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;morsure +1&lt;/i&gt;, +10 (1d4+2 plus &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#CROCENJAMBE&quot; title=&quot;Les manœuvres offensives&quot;&gt;croc-en-jambe&lt;/a&gt;) et 2 griffes
+1, +11 (1d2+2)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Voici les statistiques du chat sans la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; : &lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +9 (1d4+1 plus &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#CROCENJAMBE&quot; title=&quot;Les manœuvres offensives&quot;&gt;croc-en-jambe&lt;/a&gt;) et 2 griffes, +10 (1d2+1).
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 13, &lt;b&gt;Dex&lt;/b&gt; 22, &lt;b&gt;Con&lt;/b&gt; -, &lt;b&gt;Int&lt;/b&gt; 2, &lt;b&gt;Sag&lt;/b&gt; 12, &lt;b&gt;Cha&lt;/b&gt; 12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +2, &lt;b&gt;BMO&lt;/b&gt; +2, &lt;b&gt;DMD&lt;/b&gt; 18 (22 contre le croc-en-jambe)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +10 (+18 pour sauter), &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +5
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;tour&lt;/a&gt; (Attaque (toutes les cr&#233;atures) ! Viens ! Va chercher ! Garde ! Cherche ! Attends ! Suis !)
